Failure hypothesis: The model assumes point data directly reflects lateral position without accounting for heading changes, leading to incorrect turn decisions when the object's horizontal alignment shifts due to camera rotation. Regression: Ignoring forward offset and relying solely on horizontal fraction misaligns with actual bearing change when headings flip from +90 to -90.

```python
def decide(observation, tools):
    views = observation['views']
    frame0 = views[0]
    frame1 = views[1]
    heading0 = frame0['heading']
    heading1 = frame1['heading']
    right_of_end0 = frame0['right_of_end_m']
    right_of_end1 = frame1['right_of_end_m']
    point0 = tools.point()[0]
    point1 = tools.point()[1]

    # If both point observations exist, use them to infer turn direction
    if point0 is not None and point1 is not None:
        frac0, frac1 = point0[0], point1[0]
        # The object's horizontal position in the image changes with heading
        # If the object moved from right to left in the image, and the heading flipped,
        # the turn direction should compensate
        # A positive heading (right) means the object is ahead to the right; negative (left) ahead to the left
        # If the object is more to the right in frame0 and more to the left in frame1, likely turn left
        # If more to the left in frame0 and more to the right in frame1, likely turn right
        # But if heading flips, the relative position must be interpreted in final orientation
        if abs(heading0 - heading1) > 90:
            # Major turn — use point shift
            if frac0 > frac1:
                return 1, "right", {}
            else:
                return 1, "left", {}
        else:
            # Small turn — use heading to infer direction
            return 1, "right" if heading1 > 0 else "left", {}

    # Only one point available — use it in context of heading
    elif point0 is not None:
        frac0 = point0[0]
        # In a +90 heading, right of image is forward-right; in -90, right of image is forward-left
        # So a right-of-center point in +90 means object is right, which requires a left turn
        # In -90, right-of-center means object is left, which requires a right turn
        # But we don't know heading1 — use only available info
        if heading0 > 0:
            # First frame is right-facing: right in image = right of object
            return 1, "left" if frac0 > 0.5 else "right", {}
        else:
            # First frame is left-facing: right in image = left of object
            return 1, "right" if frac0 > 0.5 else "left", {}

    elif point1 is not None:
        frac1 = point1[0]
        if heading1 > 0:
            return 1, "left" if frac1 > 0.5 else "right", {}
        else:
            return 1, "right" if frac1 > 0.5 else "left", {}

    else:
        # No point — use match score and heading
        match_scores = tools.match()
        frame = 1 if match_scores[1] > match_scores[0] else 0
        return frame, "right" if heading1 > 0 else "left", {}
